Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "datum.PORTFOLIO_SIZE != ''inactive''"
    },
    {
      "calculate": "indexof([''single_listing'',''small_portfolio'',''medium_portfolio'',''large_portfolio''], datum.PORTFOLIO_SIZE)",
      "as": "ord"
    },
    {
      "calculate": "[''1 listing'',''2–5'',''6–15'',''16+''][datum.ord]",
      "as": "size_label"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Total Hosts",
          "as": "all_hosts"
        }
      ]
    },
    {
      "calculate": "datum[''Total Hosts''] / datum.all_hosts",
      "as": "host_share"
    }
  ],
  "hconcat": [
    {
      "width": 190,
      "height": 130,
      "layer": [
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 0,
            "fontSize": 11,
            "color": "#8A7F6E",
            "text": "HOSTS",
            "letterSpacing": 1.5
          },
          "transform": [
            {
              "aggregate": [
                {
                  "op": "count",
                  "as": "n"
                }
              ]
            }
          ]
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 22,
            "fontSize": 34,
            "color": "#14617E",
            "fontWeight": 600
          },
          "transform": [
            {
              "aggregate": [
                {
                  "op": "sum",
                  "field": "Total Hosts",
                  "as": "t"
                }
              ]
            }
          ],
          "encoding": {
            "text": {
              "field": "t",
              "format": ","
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 76,
            "fontSize": 12,
            "color": "#6B6255"
          },
          "transform": [
            {
              "filter": "datum.PORTFOLIO_SIZE == ''single_listing''"
            },
            {
              "calculate": "format(datum.host_share, ''.0%'') + '' own a single listing''",
              "as": "t"
            }
          ],
          "encoding": {
            "text": {
              "field": "t"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 96,
            "fontSize": 12,
            "color": "#B8860B",
            "fontWeight": 600
          },
          "transform": [
            {
              "filter": "datum.PORTFOLIO_SIZE == ''large_portfolio''"
            },
            {
              "calculate": "datum[''Total Hosts''] + '' hosts own '' + format(datum[''Listings Share''], ''.1%'') + '' of listings''",
              "as": "t"
            }
          ],
          "encoding": {
            "text": {
              "field": "t"
            }
          }
        }
      ]
    },
    {
      "width": 260,
      "height": 130,
      "encoding": {
        "y": {
          "field": "size_label",
          "type": "nominal",
          "title": null,
          "sort": {
            "field": "ord"
          },
          "axis": {
            "domain": false,
            "ticks": false,
            "labelColor": "#6B6255",
            "labelFontSize": 11,
            "labelPadding": 6
          }
        },
        "x": {
          "field": "Listings Share",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "nice": false
          }
        }
      },
      "layer": [
        {
          "mark": {
            "type": "bar",
            "cornerRadiusEnd": 4,
            "height": {
              "band": 0.6
            }
          },
          "encoding": {
            "color": {
              "condition": {
                "test": "datum.PORTFOLIO_SIZE == ''large_portfolio''",
                "value": "#F2B632"
              },
              "value": "#14617E"
            },
            "tooltip": [
              {
                "field": "size_label",
                "title": "Listings per host"
              },
              {
                "field": "Total Hosts",
                "title": "Hosts",
                "format": ","
              },
              {
                "field": "Listings Share",
                "title": "Share of all listings",
                "format": ".1%"
              }
            ]
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "dx": 4,
            "fontSize": 11,
            "color": "#6B6255"
          },
          "encoding": {
            "text": {
              "field": "Listings Share",
              "format": ".0%"
            }
          }
        },
        {
          "transform": [
            {
              "joinaggregate": [
                {
                  "op": "max",
                  "field": "Listings Share",
                  "as": "mx"
                }
              ]
            },
            {
              "calculate": "datum.mx * 1.25",
              "as": "pad"
            }
          ],
          "mark": {
            "type": "point",
            "opacity": 0
          },
          "encoding": {
            "x": {
              "field": "pad",
              "type": "quantitative"
            }
          }
        }
      ],
      "title": {
        "text": "Share of all listings by host size",
        "anchor": "end",
        "fontSize": 10,
        "fontWeight": "normal",
        "color": "#8A7F6E",
        "offset": 4
      }
    }
  ],
  "spacing": 16,
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI"
  }
}'
